examples.script:
Set Variable [ $r ; Value: Let([
 year = GetAsNumber(Middle(MBS( "CompileDate" );7;6))
]; year) ]

Set Variable [ $r ; Value: Let([
  id = MBS( "ECKey.CurveNameToID"; "P-256" );
  ECKey = MBS( "ECKey.Generate"; id );
  signature = MBS( "ECKey.ES256Sign"; ECKey; "Hello World"; "UTF-8"; "Base64" );
  verify = MBS("ECKey.ES256Verify"; ECKey; "Hello World"; "UTF-8"; signature; "Base64");
  description = MBS("ECKey.Description"; ECKey);
  r = MBS("ECKey.Release"; ECKey)
]; signature & ¶ & verify & ¶ & description) ]

Set Variable [ $r ; Value: Let([
   // new matrix
   matrix = MBS("Matrix.New"; 3; 4);
   // add some content
   r = MBS( "Matrix.SetRow"; matrix; 0; "00¶01¶02¶03" );
   r = MBS( "Matrix.SetRow"; matrix; 1; "10¶11¶12¶13" );
   r = MBS( "Matrix.SetRow"; matrix; 2; "20¶21¶22¶23" );
   // creates a second matrix
   matrix2 = MBS("Matrix.New"; 1; 4);
   r = MBS( "Matrix.SetRow"; matrix2; 0; "a¶b¶c¶d" );
   // copy content of first matrix to second
   r = MBS( "Matrix.Append"; matrix; matrix2  );
   // output matrix to check
   csv = MBS("Matrix.CSV"; matrix)
]; csv) ]

Set Variable [ $r ; Value: Let ( [
 m = MBS("Matrix.New"; 1; 1);
 r = MBS("Matrix.SetValue"; m; 0; 0; "Hello" & Char ( 10 ) & "World¶Test");
 csv = MBS("Matrix.CSV"; m);
 r = MBS("Matrix.Release"; m)
]; csv ) ]

Set Variable [ $r ; Value: Let ([

matrix = MBS( "Matrix.CSVSplit"; "FirstName;LastName;City¶Joe;Miller;Las Vegas¶Bob;\"Johnson-Meyer\";\"Köln\"");
text = MBS("Matrix.CSV"; matrix);
r = MBS("Matrix.Release"; matrix)

]; text ) ]

Set Variable [ $r ; Value: Let([
   text = MBS ( "Text.ReadTextFile"; "/Users/cs/Documents/test.csv"; "utf-8");
   matrix = MBS( "Matrix.CSVSplit"; text; ","; 1 );
   json = MBS("Matrix.JSONRecords"; matrix; "");
   r = MBS("Matrix.Release"; matrix)
]; json) ]

Set Variable [ $r ; Value: Let([
   // new matrix
   matrix = MBS("Matrix.New"; 3; 4);
   // add some content
   r = MBS( "Matrix.SetRow"; matrix; 0; "00¶01¶02¶03" );
   r = MBS( "Matrix.SetRow"; matrix; 1; "10¶11¶12¶13" );
   r = MBS( "Matrix.SetRow"; matrix; 2; "20¶21¶22¶23" );
   // creates a second matrix
   matrix2 = MBS("Matrix.New"; 2; 2);
   // copy content of first matrix to second
   r = MBS( "Matrix.CopyContent"; matrix; matrix2  );
   // output second matrix to check
   csv = MBS("Matrix.CSV"; matrix2)
]; csv) ]

Set Variable [ $r ; Value: Let([

m = MBS("Matrix.New"; 7; 2);
s = MBS("Matrix.SetColumn"; m; 0; "10/23/71¶5.4.68¶16.555555¶garbage¶4-8-2003¶50/3/2356¶5.4.68" );
s = MBS("Matrix.SetColumn"; m; 1; "10/23/71¶5.4.68¶16.555555¶garbage¶4-8-2003¶50/3/2356¶5.4.68" );
e = "if ( GetAsText(GetAsDate ( current )) = \"?\" ; \"\" ; GetAsDate ( current ) )"; 
s = MBS("Matrix.Evaluate"; m; e; 1; 6; 1; 1; 2);

r = MBS("Matrix.Text"; m; ""; ""; ""; ""; ""; " => ")
];r) ]

Set Variable [ $r ; Value: Let ([
// split a CSV
matrix = MBS( "Matrix.CSVSplit"; "FirstName;LastName;City¶Joe;Miller;Las Vegas¶Bob;\"Johnson-Meyer\";\"Köln\"");
// now move first row into column names
firstRow = MBS("Matrix.GetRow"; matrix; 0);
r = MBS("Matrix.SetColumnNames"; matrix; firstRow);
r = MBS("Matrix.RemoveRow"; matrix; 0);
// now you can use column names to find columns!
text = MBS("Matrix.GetValue"; matrix; 0; "City");
r = MBS("Matrix.Release"; matrix)

]; text ) ]

Set Variable [ $r ; Value: Let([
matrix = MBS("Matrix.New"; 5; 5);
r = MBS( "Matrix.SetRow"; matrix; 0; "1¶3" );
r = MBS( "Matrix.SetRow"; matrix; 2; "123¶5" );
r = MBS( "Matrix.SetRow"; matrix; 3; "3¶4" );
index = MBS( "Matrix.IndexOfFirstValueMatching"; matrix; 0; "="; 123 )
]; index) ]

Set Variable [ $r ; Value: Let([
matrix = MBS("Matrix.New"; 5; 5);
r = MBS( "Matrix.SetRow"; matrix; 0; "1¶3" );
r = MBS( "Matrix.SetRow"; matrix; 2; "123¶5" );
r = MBS( "Matrix.SetRow"; matrix; 3; "Hello¶4" );
index1 = MBS( "Matrix.IndexOfFirstValueMatching"; matrix; 0; "prefix"; "He" );
index2 = MBS( "Matrix.IndexOfFirstValueMatching"; matrix; 0; "postfix"; "23" );
index3 = MBS( "Matrix.IndexOfFirstValueMatching"; matrix; 1; "="; "4" )
]; index1 & ¶ & index2 & ¶ & index3) ]

Set Variable [ $r ; Value: Let([
   matrix = MBS("Matrix.New"; 4; 4);
   r = MBS( "Matrix.SetRow"; matrix; 0; "00¶01¶02¶03"  );
   r = MBS( "Matrix.SetRow"; matrix; 1; "10¶11¶12¶13"  );
   r = MBS( "Matrix.SetRow"; matrix; 2; "20¶21¶22¶23"  );
   r = MBS( "Matrix.SetRow"; matrix; 3; "30¶31¶32¶33"  );
   r = MBS("Matrix.InsertRow"; matrix; 2);
   csv = MBS("Matrix.CSV"; matrix)
]; csv) ]

Set Variable [ $r ; Value: let([
m = MBS("Matrix.New"; 3; 3);
r = MBS("Matrix.Lookup"; m; 5; 5; "test")
]; r) ]

Set Variable [ $r ; Value: let([
m = MBS("Matrix.New"; 3; 3);
s = MBS("Matrix.SetValue"; m; 2; 2; "value");
r = MBS("Matrix.Lookup"; m; 2; 2; "test")
]; r) ]

Set Variable [ $r ; Value: let([ 
  m = MBS("Matrix.New"; 3; 1);
  s = MBS("Matrix.SetValue"; m; 0; 0; "Hello");
  s = MBS("Matrix.SetValue"; m; 1; 0; " ");
  s = MBS("Matrix.SetValue"; m; 2; 0; "World");
  r = MBS("Matrix.MBS"; m; "Text.Concat");
  m = MBS("Matrix.Release"; m)
]; r) ]

Set Variable [ $r ; Value: Let(
	[
		m = MBS( "Matrix.New" ; 4 ; 1 ) ;
		s = MBS( "Matrix.SetValue" ; m ; 0 ; 0 ; "FileMaker" ) ;

		// Row 1 left empty 
		s = MBS( "Matrix.SetValue" ; m ; 2 ; 0 ; " Plugin" ) ;
		s = MBS( "Matrix.SetValue" ; m ; 3 ; 0 ; " Rocks!" ) ;
		r = MBS( "Matrix.MBS" ; m ; "Text.Concat" ) ;
		m = MBS( "Matrix.Release" ; m )
	] ;
	r
) ]

Set Variable [ $r ; Value: Let ([
  // split a CSV
  matrix = MBS( "Matrix.CSVSplit"; "FirstName;LastName;City¶Joe;Miller;Las Vegas¶Bob;\"Johnson-Meyer\";\"Köln\"");
  // swap first and second row
  r = MBS("Matrix.SearchAndReplace"; matrix; "ö"; "oe");
  // and ask for text back with column names in first row
  text = MBS("Matrix.CSV"; matrix);
  r = MBS("Matrix.Release"; matrix)
]; text ) ]

Set Variable [ $r ; Value: Let ([
// split a CSV
matrix = MBS( "Matrix.CSVSplit"; "FirstName;LastName;City¶Joe;Miller;Las Vegas¶Bob;\"Johnson-Meyer\";\"Köln\"");
// now move first row into column names
firstRow = MBS("Matrix.GetRow"; matrix; 0);
r = MBS("Matrix.SetColumnNames"; matrix; firstRow);
r = MBS("Matrix.RemoveRow"; matrix; 0);
// and ask for text back with column names in first row
text = MBS("Matrix.CSV"; matrix;"";"";"";"";"";",";2);
r = MBS("Matrix.Release"; matrix)

]; text ) ]

Set Variable [ $r ; Value: Let ([
  // split a CSV
  matrix = MBS( "Matrix.CSVSplit"; "FirstName;LastName;City¶Joe;Miller;Las Vegas¶Bob;\"Johnson-Meyer\";\"Köln\"");
  // swap first and second row
  r = MBS("Matrix.SwapColumns"; matrix; 1; 2);
  // and ask for text back with column names in first row
  text = MBS("Matrix.CSV"; matrix);
  r = MBS("Matrix.Release"; matrix)
]; text ) ]

Set Variable [ $r ; Value: Let ([
  // split a CSV
  matrix = MBS( "Matrix.CSVSplit"; "FirstName;LastName;City¶Joe;Miller;Las Vegas¶Bob;\"Johnson-Meyer\";\"Köln\"");
  // swap first and second row
  r = MBS("Matrix.SwapRows"; matrix; 1; 2);
  // and ask for text back with column names in first row
  text = MBS("Matrix.CSV"; matrix);
  r = MBS("Matrix.Release"; matrix)
]; text ) ]

Set Variable [ $r ; Value: Let([
  // we need to connect
 sock = MBS( "Socket.Connect"; "monkeybreadsoftware.de"; 80 );
 // now we can get the IP used to connect
 localIP = MBS( "Socket.LocalIP"; sock );
 r = MBS("Socket.Close"; sock)]; 
localIP) ]

Set Variable [ $r ; Value: MBS( "Socket.WriteHex"; $sock; "02064F07A203" )

// sends
// <STX><6><CMD_ON><channels><CHECKSUM><ETX>
// In Hex : 0x02 0x06 0x4f 0x07 0xa2 0x03 ]

Set Variable [ $r ; Value: Let([
  session = MBS( "Translation.StartSession"; "de"; "en");
  text = MBS( "Translation.TranslateString"; session; "Hallo Leute");
  r = MBS("Translation.Release"; session)
]; text) ]

Set Variable [ $r ; Value: Let([
  session = MBS( "Translation.StartSession"; "de"; "en");
  json = "[]";
  json = JSONSetElement ( json ; "[+].sourceText" ; "Hallo Leute" ; JSONString );
  json = JSONSetElement ( json ; "[+].sourceText" ; "Man sieht sich bei der Konferenz!" ; JSONString );
  text = MBS( "Translation.Translations"; session; json);
  r = MBS("Translation.Release"; session)
]; text) ]

Set Variable [ $r ; Value: Let([
  session = MBS( "Translation.StartSession"; "de"; "en");
  json = "[]";
  json = JSONSetElement ( json ; "[+].sourceText" ; "Hallo Leute" ; JSONString );
  json = JSONSetElement ( json ; "[:].clientIdentifier" ; "1" ; JSONString );
  json = JSONSetElement ( json ; "[+].sourceText" ; "Man sieht sich bei der Konferenz!" ; JSONString );
  json = JSONSetElement ( json ; "[:].clientIdentifier" ; "2" ; JSONString );
  text = MBS( "Translation.Translations"; session; json);
  r = MBS("Translation.Release"; session)
]; text) ]
